"""Local fixture lifecycle proofs; mocks model orchestration failures only.
No backend conformance is claimed by these deterministic checks.
"""
import ast
import json
import re
import shutil
import subprocess
import sys
import tempfile
import types
import unittest
import uuid
from pathlib import Path

SOURCE = Path(sys.argv.pop(1))


class InterruptedSetup(BaseException):
    pass


class Lifecycle(unittest.TestCase):
    def exercise(self, fail_at=None, interrupt=False, preexisting=False):
        tree = ast.parse(SOURCE.read_text())
        fixture = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == 'kind')
        fixture.decorator_list = []
        resources = {'cluster': preexisting, 'volume': preexisting, 'attachment': False}
        calls = []
        with tempfile.TemporaryDirectory() as root:
            def fault(stage):
                if fail_at == stage:
                    if interrupt:
                        raise InterruptedSetup(stage)
                    raise RuntimeError(stage)

            def run(cmd, **kw):
                calls.append(cmd)
                stdout = ''
                if cmd[:3] == ['kind', 'get', 'clusters']:
                    stdout = 'ocor-poc\n' if resources['cluster'] else ''
                elif cmd[:3] == ['kind', 'create', 'cluster']:
                    resources.update(cluster=True, volume=True)
                    fault('create')
                elif cmd[:3] == ['kind', 'delete', 'cluster']:
                    resources.update(cluster=False, volume=False, attachment=False)
                elif cmd[:3] == ['docker', 'network', 'connect']:
                    resources['attachment'] = True
                    fault('attach')
                elif cmd[:3] == ['docker', 'network', 'inspect']:
                    stdout = json.dumps([{'Containers': {}}])
                elif cmd[:2] == ['docker', 'exec']:
                    fault('image')
                elif cmd[:2] == ['docker', 'inspect']:
                    return subprocess.CompletedProcess(cmd, 0 if resources['cluster'] else 1,
                                                       '{}', '' if resources['cluster'] else 'Error: No such object')
                elif cmd[:2] == ['helm', '--kube-context']:
                    fault('helm')
                return subprocess.CompletedProcess(cmd, 0, stdout, '')

            def kubectl(*args, **kwargs):
                calls.append(['kubectl', *args])
                if args[:2] == ('create', 'namespace'):
                    fault('namespace')
                return subprocess.CompletedProcess(args, 0, '', '')

            ns = dict(subprocess=types.SimpleNamespace(run=run), KIND_CLUSTER='ocor-poc',
                      KIND_NODE_IMAGE='verified:pin', KIND_VAULT_ROOT=Path(root)/'vault',
                      BOOTSTRAP_NETWORK='ocor-bootstrap_ocor-bootstrap', BOOTSTRAP_SERVICES=[],
                      OTHER_OPS_IMAGE='other:pin', CHART_DIR=Path(root),
                      tool=lambda name: name, helm_profile=lambda: {'images': {'pins': {'ops': 'ops:pin'}}},
                      kubectl=kubectl, yaml=types.SimpleNamespace(safe_dump=json.dumps,
                                                                safe_dump_all=lambda rows: json.dumps(list(rows))),
                      time=types.SimpleNamespace(sleep=lambda _: None), os=types.SimpleNamespace(getuid=lambda: 1000,
                                                                                                   environ={}),
                      uuid=uuid, json=json, re=re, shutil=shutil, make_writable=lambda p: None)
            exec(compile(ast.Module(body=[fixture], type_ignores=[]), str(SOURCE), 'exec'), ns)
            stack = types.SimpleNamespace(work=Path(root), env={'OCOR_LOCAL_OPENBAO_TOKEN': 'local',
                                                                'OCOR_LOCAL_POSTGRES_PASSWORD': 'local'},
                                          operator_token='local')
            gen = ns['kind'](stack)
            if fail_at:
                with self.assertRaises(InterruptedSetup if interrupt else RuntimeError):
                    next(gen)
            else:
                ctx = next(gen)
                self.assertIn('namespace', ctx)
                gen.close()
            self.assertEqual(resources['cluster'], preexisting)
            self.assertEqual(resources['volume'], preexisting)
            if not preexisting:
                self.assertFalse(resources['attachment'])
                self.assertIn(['kind', 'delete', 'cluster', '--name', 'ocor-poc'], calls)
            else:
                self.assertNotIn(['kind', 'delete', 'cluster', '--name', 'ocor-poc'], calls)

    def test_failure_after_node_creation(self): self.exercise('create')
    def test_interrupt_during_creation(self): self.exercise('create', interrupt=True)
    def test_interrupt_after_network_attachment(self): self.exercise('attach', interrupt=True)
    def test_failure_loading_image(self): self.exercise('image')
    def test_failure_creating_namespace(self): self.exercise('namespace')
    def test_failure_before_helm_yield(self): self.exercise('helm')
    def test_success_yield_then_close(self): self.exercise()
    def test_preexisting_cluster_preserved(self): self.exercise(preexisting=True)


if __name__ == '__main__':
    unittest.main()
